import React, { useContext, useState } from "react";
import { CartContext } from "../context/cartContext";
import { graphql, Link } from "gatsby";
import Layout from "../components/layout";
import { UserProfile } from "../interfaces";
import data from "../data/data.json";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { FiArrowLeft } from "react-icons/fi";
import { db } from "../../firebaseConfig";
import { collection, addDoc } from "firebase/firestore";
import emailjs from "emailjs-com";
import PayPalButton from "../components/paypalButton";
import Calendar from "react-calendar";
import "react-calendar/dist/Calendar.css";

const CheckoutPage = () => {
  const { t } = useTranslation();
  const cartContext = useContext(CartContext);
  const [customerEmail, setCustomerEmail] = useState("");
  const [customerName, setCustomerName] = useState("");
  const [customerPhone, setCustomerPhone] = useState("");
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  // const [showCalendar, setShowCalendar] = useState(false);
  const [orderConfirmed, setOrderConfirmed] = useState(false);

  if (!cartContext) {
    return <div>{t("cart.cartContextError")}</div>;
  }

  const userData: UserProfile = data;
  const { cart, clearCart } = cartContext;
  const total = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

  const isSunday = (date: Date): boolean => date.getDay() === 0;
  const minDate = new Date();
  minDate.setDate(minDate.getDate() + 7);

  interface Order {
    customerName: string;
    customerEmail: string;
    customerPhone: string;
    items: typeof cart;
    total: number;
    date: string;
  }

  const formattedOrderDetails = cart
    .map(
      (item) =>
        `${item.name} | ${t("cart.quantity")}: ${item.quantity} | ${t(
          "cart.price"
        )}: ${(item.price * item.quantity).toFixed(2)} $`
    )
    .join("\n");

  async function handleTransactionComplete(
    customerName: string,
    customerEmail: string
  ): Promise<void> {
    if (!customerEmail || !customerName) {
      alert(t("cart.enter_name_email"));
      return;
    }
    if (!selectedDate) {
      alert('t("cart.select_delivery_date")');
      return;
    }
    // setShowCalendar(true);
    confirmDeliveryDate(total, formattedOrderDetails, total.toFixed(2));
  }

  async function confirmDeliveryDate(
    total: number,
    orderDetails: string,
    totalAmount: string
  ) {
    if (!selectedDate) {
      return;
    }

    const formattedDate = selectedDate.toLocaleDateString("fr-CA"); // Formato YYYY-MM-DD

    // Guardar pedido en Firestore
    try {
      const order: Order = {
        customerName,
        customerEmail,
        customerPhone,
        items: cart,
        total: total,
        date: new Date().toISOString(),
      };
      const orderRef = await addDoc(collection(db, "orders"), order);
      console.log("Pedido guardado con ID:", orderRef.id);
    } catch (error) {
      console.error("Error guardando el pedido:", error);
    }

    // Enviar correo con EmailJS
    try {
      const templateParams = {
        to_name: "Service Client Succulente Sculpture",
        from_name: customerName,
        reply_to: customerEmail,
        phone: customerPhone,
        order_details: orderDetails,
        total_amount: totalAmount,
        delivery_date: formattedDate,
      };

      const serviceID = "service_3b7eaqj"; // Reemplaza con tu service ID de EmailJS
      const templateID = "template_jyqdnxg"; // Reemplaza con tu template ID de EmailJS
      const userID = "u2Op-9wm_t5yR4it5"; // Reemplaza con tu user ID de EmailJS

      const response = await emailjs.send(
        serviceID,
        templateID,
        templateParams,
        userID
      );
      console.log("Correo enviado con éxito:", response.status, response.text);
    } catch (error) {
      console.error("Error enviando correo:", error);
    }
    setOrderConfirmed(true);
  }

  return (
    <Layout data={userData}>
      <div className="container mx-auto p-4 relative mt-4">
        {orderConfirmed ? (
          <div className="text-center bg-primary text-secondary p-6 rounded-lg shadow-md">
            <h2 className="text-3xl font-bold mb-4">{t("cart.thank_you")}</h2>

            <h3 className="text-2xl font-bold mb-4">
              {t("instructions.title")}
            </h3>

            <ul className="text-lg text-pink text-left max-w-3xl mx-auto">
              {(
                t("instructions.content", { returnObjects: true }) as any[]
              ).map((item, index) => (
                <li key={index} className="my-4">
                  {index + 1}. {item.title}{" "}
                  <span
                    key={index}
                    className="mb-4"
                    dangerouslySetInnerHTML={{ __html: item.copy }}
                  ></span>
                </li>
              ))}
            </ul>

            <Link
              to="/"
              className="bg-secondary text-light px-6 py-3 rounded mt-6 inline-block"
              onClick={clearCart}
            >
              {t("cart.return_home")}
            </Link>
          </div>
        ) : (
          <>
            <div className="flex justify-between items-center mb-4">
              <h1 className="text-secondary text-3xl">{t("cart.checkout")}</h1>
              <Link
                to="/cart"
                className="bg-secondary text-light px-4 py-2 rounded flex items-center text-2xl"
              >
                <FiArrowLeft className="text-2xl mr-4" /> {t("cart.backToCart")}
              </Link>
            </div>

            <div className="bg-primary text-secondary p-6 rounded-lg shadow-md">
              <h2 className="text-2xl font-bold mb-4">
                {t("cart.purchaseSummary")}
              </h2>
              <div className="space-y-2">
                {cart.map((item) => (
                  <div key={item.id} className="flex justify-between">
                    <span>
                      {item.name} (x{item.quantity})
                    </span>
                    <span>${(item.price * item.quantity).toFixed(2)}</span>
                  </div>
                ))}
              </div>
              <div className="text-xl border-t mt-4 pt-4">
                <div className="flex justify-between font-bold text-3xl">
                  <span>{t("cart.total")}</span>
                  <span>${total.toFixed(2)}</span>
                </div>
              </div>
            </div>

            <div className="bg-primary text-secondary mt-8 p-6 rounded-lg shadow-md">
              <h2 className="text-2xl font-bold mb-4">
                {t("cart.paymentInfo")}
              </h2>
              <div className="flex flex-col sm:flex-row space-y-4 sm:space-y-0 sm:space-x-4 items-center">
                <label className={styles.label}>{t("cart.name")}</label>
                <input
                  className={styles.input}
                  type="text"
                  value={customerName}
                  onChange={(e) => setCustomerName(e.target.value)}
                  required
                />
                <label className={styles.label}>{t("cart.email")}</label>
                <input
                  className={styles.input}
                  type="email"
                  value={customerEmail}
                  onChange={(e) => setCustomerEmail(e.target.value)}
                  required
                />
                <label className={styles.label}>{t("cart.phone")}</label>
                <input
                  className={styles.input}
                  type="phone"
                  value={customerPhone}
                  onChange={(e) => setCustomerPhone(e.target.value)}
                  required
                />
              </div>

              <h2 className="text-2xl font-bold mb-4 text-center mt-8">
                {t("cart.select_delivery_date")}
              </h2>
              <Calendar
                onChange={(value) => setSelectedDate(value as Date)}
                value={selectedDate}
                tileDisabled={({ date }) => !isSunday(date) || date < minDate}
                minDate={minDate}
                className="mx-auto"
              />

              {/* Deshabilitar el botón si los campos están vacíos */}
              <div className="mx-auto mt-8 w-1/2">
                {customerName && customerEmail && selectedDate ? (
                  // <PayPalButton
                  //   customerName={customerName}
                  //   customerEmail={customerEmail}
                  //   customerPhone={customerPhone}
                  //   onTransactionComplete={handleTransactionComplete}
                  // />
                  <button
                    onClick={() =>
                      confirmDeliveryDate(
                        total,
                        formattedOrderDetails,
                        total.toFixed(2)
                      )
                    }
                    className="bg-secondary text-light px-4 py-2 rounded mt-4 mx-auto block"
                  >
                    {t("cart.submit_order")}
                  </button>
                ) : (
                  <p className="text-secondary text-center">
                    {t("cart.enter_name_email_date")}
                  </p>
                )}
              </div>
            </div>
            {/* {showCalendar && (
            <div className="bg-primary text-secondary mt-8 p-6 rounded-lg shadow-md">
              <h2 className="text-2xl font-bold mb-4 text-center">
                {t("cart.select_delivery_date")}
              </h2>
              <Calendar
                onChange={(value) => setSelectedDate(value as Date)}
                value={selectedDate}
                tileDisabled={({ date }) => !isSunday(date) || date < minDate}
                minDate={minDate}
                className="mx-auto"
              />
              <button
                onClick={() =>
                  confirmDeliveryDate(
                    total,
                    formattedOrderDetails,
                    total.toFixed(2)
                  )
                }
                className="bg-secondary text-light px-4 py-2 rounded mt-4 mx-auto block"
              >
                {t("cart.confirm_date")}
              </button>
            </div>
          )} */}
          </>
        )}
      </div>
    </Layout>
  );
};

export default CheckoutPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  input:
    "bg-semilight placeholder:text-light text-light text-xl w-full p-2 border rounded",
  label: "block text-lg font-medium mb-1",
};
